function Wait-WinRt($op, [int]$ms) {
    $deadline = (Get-Date).AddMilliseconds($ms)
    while ($op.Status.ToString() -eq 'Started' -and (Get-Date) -lt $deadline) {
        Start-Sleep -Milliseconds 50
    }
    return $op
}

