# 脚本会把剪贴板里现有的内容原样再写一次，观察 1.2 秒内是否被别的程序改掉。

$ErrorActionPreference = 'Stop'

function Show([string]$label, [string]$text) {
    $len = if ($null -eq $text) { 0 } else { $text.Length }
    $head = if ($len -gt 12) { $text.Substring(0, 12) } else { $text }
    $tail = if ($len -gt 8) { $text.Substring($len - 8) } else { "" }
    Write-Host ("{0,-10} 长度={1}  头={2}  尾={3}" -f $label, $len, $head, $tail)
